/**
 * lib/data/real-doctors.ts
 *
 * Healthcare practitioner & facility contacts directory with explicit provenance tracking.
 *
 * Data Provenance Taxonomy:
 * 1. Independently Verified Clinicians:
 *    Apex public hospital consultants (AIIMS, GMCs) with confirmed medical council registrations.
 *    verificationStatus: 'independently_verified'
 *    recordType: 'clinician'
 *
 * 2. Source-Confirmed Clinicians:
 *    Practitioners from reviewed medical registries (Practo) with authentic patient feedback metrics.
 *    verificationStatus: 'source_confirmed'
 *    recordType: 'clinician'
 *
 * 3. Source-Confirmed Facility Nodal Contacts:
 *    Institutional medical contacts from the official National Health Authority AB-PMJAY dataset.
 *    verificationStatus: 'source_confirmed'
 *    recordType: 'facility_nodal_contact'
 *    (Credentials not independently verified; no synthetic degrees or ratings applied)
 */

export type VerificationStatus = 'unverified' | 'source_confirmed' | 'independently_verified'
export type RecordType = 'clinician' | 'facility_nodal_contact'

export interface RealDoctor {
  id: string
  name: string
  qualifications?: string
  regNo?: string // Verified NMC or State Medical Council Registration Number
  specialty: 'general' | 'cardiology' | 'pediatrics' | 'gynecology' | 'orthopedics' | 'neurology' | 'pulmonology' | 'oncology' | 'ent' | 'dermatology'
  specialtyName: string
  experience?: number // Years of practice (only if supported by source)
  rating?: number // Clinical rating (only if supported by verified patient reviews)
  reviewCount?: number
  patientRecommendationPercent?: number
  hospitalAffiliation: string
  stateCode: string // LGD State Code e.g. "23" for MP, "07" for Delhi
  stateName: string
  districtName: string
  location: string
  phone: string
  opdTimings?: string
  consultationFee: number
  verified: boolean // backward compatibility
  verificationStatus: VerificationStatus // Explicit provenance status
  recordType: RecordType // Distinguishes individual doctors from hospital contacts
  sourceName: string
  sourceRecordId?: string
  sourceUrl?: string
  lastVerifiedAt?: string
  available: boolean
  lat: number
  lon: number
  bio: string
  distance?: number // Computed dynamically at runtime based on user GPS or selected district
}

